# Simon Tufts the third (1750-1801/2), "Merchant of India": Coolidge, MHR XLI no. 3 (Sept 1938), pp. 33-47 (Nov 17 run)
S3_IA = "https://archive.org/details/medfordhistorica12medf/page/n68/mode/1up"
S3_SRC = 'Ruth Dame Coolidge, &ldquo;Simon Tufts the Third, Merchant of India,&rdquo; <em>Medford Historical Register</em> XLI, no. 3 (September 1938)'
IMAGES["home-of-dr-simon-tufts-high-forest-1938.jpg"] = ("The Home of Dr. Simon Tufts, corner of High and Forest Streets, Medford",
  "Frontispiece of <em>Medford Historical Register</em> XLI, no. 3 (September 1938), facing p. 33. Simon Tufts the third (1750&ndash;1801/2) said in a 1792 letter that he was born in &ldquo;the house in the Square.&rdquo;",
  "Medford Historical Society, <em>Medford Historical Register</em> XLI (1938), via Internet Archive", "Shown for non-commercial historical use",
  "https://archive.org/details/medfordhistorica12medf/page/n67/mode/1up", "Internet Archive")
IMAGES["mhr-xli-simon-tufts-family-tomb-clip.jpg"] = ("Clipping: inscription of the Tufts family tomb, Salem Street burying ground, Medford",
  "Detail of p. 33, <em>Medford Historical Register</em> XLI, no. 3 (September 1938), from Coolidge&rsquo;s &ldquo;Simon Tufts the Third, Merchant of India.&rdquo;",
  "Medford Historical Society, <em>Medford Historical Register</em> XLI (1938), via Internet Archive", "Shown for non-commercial historical use", S3_IA, "Internet Archive (full page)")
S3_C = lambda t: ' <span class="note">(' + S3_SRC + ', ' + t + ')</span>'
S3_TOMB = ("The family tomb of Simon Tufts Esq. First Physician of Medford. He died 3 Jan. 1747 aged 47 ys. Simon Tufts Esq. F. M. S. his son &amp; successor, who died 3 Dec. 1786 aged 60. "
  "Both eminent in their profession; just towards man, &amp; devout towards God. Abigail Smith, his mother, died 1790 aged 90 y&rsquo;s. Lucy Dudley, his first wife, 1768 &mdash; 41 y&rsquo;s. "
  "Elizabeth Hall, second do. 30 Aug. 1830, 87 y&rsquo;s 3 mo&rsquo;s. Simon Tufts A. M. Oldest son at Cape Good Hope in 1802 Aged 52 y&rsquo;s. Hall Tufts A. M. 4th son at Surinam, 19 July 1801 Aged 26 y&rsquo;s. "
  "Cotton Tufts A. M. ob 12 Feb. 1835 Ae. 63. Turell Tufts Esq. Ob June 9, 1842 Aged 72.")
S3_STORY = ('<section class="story-brief" id="merchant-of-india"><h3>Merchant of India: His Story in His Own Letters</h3>'
 + FIG("home-of-dr-simon-tufts-high-forest-1938.jpg", "hfig-flow mi-inline")
 + '<p>Simon Tufts was the first son of ' + PL("simon-tufts-11-1", "Dr. Simon Tufts") + ' and Lucy (Dudley) Tufts, born in Medford in 1750. His favorite sister, Lucy, born in 1752, married Benjamin Hall, Jr., in 1777, and his half-brother was ' + PL("turell-tufts", "Turell Tufts") + '. Ruth Dame Coolidge found that he &ldquo;does not seem to have served in the Revolution.&rdquo;' + S3_C("pp. 35&ndash;36") + '</p>'
 + '<p>His later life is told in a series of letters he wrote to his brother-in-law Benjamin Hall, Jr., preserved among the Hall papers of the Medford Historical Society and copied by the Works Progress Administration in 1938. In 1787, writing from London after learning of his father&rsquo;s death, he said he would soon &ldquo;embark for Ostend and thence to the East Indies,&rdquo; and that he had sent &ldquo;my picture in a shagreen case by Captain Scott&rdquo; for his sister Lucy.' + S3_C("pp. 37&ndash;38") + '</p>'
 + '<p>His ship reached Bombay on January 19, 1788. A post he had been promised, under an Englishman acting as agent for the Emperor of Germany in India, ended when that man died. On Prince of Wales&rsquo;s Island (Penang) he lost the use of his limbs for two months; the ship carrying his goods to Bengal was never heard of again. He reached Calcutta on March 29 and took charge of works at Omeidpore, about 18 miles away, that had once been &ldquo;the most extensive works, in India of Rum Indigo. Sugar. &amp; Silk.&rdquo;' + S3_C("letter of Dec. 8, 1789, pp. 38&ndash;39") + '</p>'
 + '<p>Letters from Omeidpore in 1792 and 1793 settle his share of his father&rsquo;s estate. The farm house and barn had been set off to him, &ldquo;not the dwelling house in which I was born&rdquo; (the editor notes: &ldquo;The house in the Square&rdquo;). The land joined the twenty-nine acres belonging to his sister, &ldquo;making in the whole Sixty two acres,&rdquo; and he asked that it be kept together. He gave Lucy the family plate left to him, and he sent his respects to &ldquo;our old Friend Gen<sup>l</sup>. Brooks and all my friends in Medford for I have and alway shall have a Regard for the little place from which I drew my first breath.&rdquo;' + S3_C("pp. 40&ndash;43") + '</p>'
 + '<p>Failing health drove him to Cape Town by May 1797. There he set up a young man in the firm of Bray, Venables &amp; Co., and in March 1801 he reported that rum from Benjamin Hall&rsquo;s Medford distillery &ldquo;has been lik&rsquo;d at the Cape by the Dutch People.&rdquo; He still hoped to visit his native country. Instead, a Cape Town firm wrote to Mrs. Lucy Hall that her brother had died &ldquo;on the fifteenth of the present month&rdquo;; his will left her the property from their father&rsquo;s estate and &pound;1,032 10s. held in London.' + S3_C("pp. 44&ndash;47") + '</p>'
 + FIG("mhr-xli-simon-tufts-family-tomb-clip.jpg", "hfig-flow mi-inline")
 + '<p>He is remembered on the family tomb in Medford&rsquo;s first burying ground, on Salem Street by the gate, which Coolidge transcribed:</p>'
 + Q(S3_TOMB, S3_SRC + ', p. 33. <a href="' + S3_IA + '">View the page scan</a>')
 + UNV("<strong>Date of death:</strong> the tomb says 1802, aged 52; <em>Tufts Kinsmen</em> Vol. I gives December 1801. The executors&rsquo; letter quoted by Coolidge is dated only &ldquo;1801&rdquo; in her text. <strong>Loyalist record:</strong> Coolidge does not mention the 1775&ndash;1778 charges recorded in <em>Tufts Kinsmen</em>. <strong>Portrait:</strong> the miniature &ldquo;in a shagreen case&rdquo; sent to Lucy Hall in 1787 has not been traced; it may survive among Hall family or Medford Historical Society holdings. Note: Pending further work.")
 + '</section>')
S3_FATHER = ('<p class="note">His eldest son&rsquo;s letters from India and the Cape (1787&ndash;1801), and the inscription of the family tomb in the Salem Street burying ground, are given on ' + PL("simon-tufts-29-1", "Simon Tufts (1750&ndash;1801)") + '. <a href="' + S3_IA + '">Source: <em>Medford Historical Register</em> XLI (1938), p. 33</a>.</p>')
for _p in PROFILES:
    if _p["slug"] == "simon-tufts-29-1" and "merchant-of-india" not in _p["bio"]:
        _p["bio"] = _p["bio"] + S3_STORY
    if _p["slug"] == "simon-tufts-11-1" and "merchant-of-india" not in _p["bio"] and "simon-tufts-29-1.html\">Simon Tufts (1750&ndash;1801)</a>. <a" not in _p["bio"]:
        _p["bio"] = _p["bio"] + FIG("home-of-dr-simon-tufts-high-forest-1938.jpg", "hfig-flow mi-inline") + S3_FATHER
